    thread_id TEXT NOT NULL, provider_key TEXT NOT NULL, provider_event_id TEXT NOT NULL,
    PRIMARY KEY (thread_id, provider_key, provider_event_id)
  )`;
  // The expanded reducer must replay from the event stream, not consume ATT-01's final rows as historical state.
  yield* sql`DELETE FROM projection_thread_attention_current`;
  yield* sql`DELETE FROM projection_thread_attention_context`;
  yield* sql`DELETE FROM projection_state WHERE projector = 'projection.thread-attention-current'`;
});

import { NonNegativeInt } from "@t3tools/contracts";
import * as SqlClient from "effect/unstable/sql/SqlClient";
import * as SqlSchema from "effect/unstable/sql/SqlSchema";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";

import { toPersistenceSqlError } from "../Errors.ts";

import {
  ProjectionStateRepository,
  type ProjectionStateRepositoryShape,
  GetProjectionStateInput,
  ProjectionState,
} from "../Services/ProjectionState.ts";

const MinLastAppliedSequenceRowSchema = Schema.Struct({
  minLastAppliedSequence: Schema.NullOr(NonNegativeInt),
});

const makeProjectionStateRepository = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;

  const upsertProjectionStateRow = SqlSchema.void({
    Request: ProjectionState,
    execute: (row) =>
      sql`
        INSERT INTO projection_state (
          projector,
          last_applied_sequence,
          updated_at
        )
        VALUES (
          ${row.projector},
          ${row.lastAppliedSequence},
          ${row.updatedAt}
        )
        ON CONFLICT (projector)
        DO UPDATE SET
          last_applied_sequence = excluded.last_applied_sequence,
          updated_at = excluded.updated_at
      `,
  });

  const upsertProjectionStateRows = SqlSchema.void({
    Request: Schema.Array(ProjectionState),
    execute: (rows) =>
      rows.length === 0
        ? Effect.void
        : sql`
            INSERT INTO projection_state ${sql.insert(
              rows.map((row) => ({
                projector: row.projector,
                last_applied_sequence: row.lastAppliedSequence,
                updated_at: row.updatedAt,
              })),
            )}
            ON CONFLICT (projector)
            DO UPDATE SET
              last_applied_sequence = excluded.last_applied_sequence,
              updated_at = excluded.updated_at
            WHERE excluded.last_applied_sequence >= projection_state.last_applied_sequence
          `,
  });

  const getProjectionStateRow = SqlSchema.findOneOption({
    Request: GetProjectionStateInput,
    Result: ProjectionState,
    execute: ({ projector }) =>
      sql`
        SELECT
          projector,
          last_applied_sequence AS "lastAppliedSequence",
          updated_at AS "updatedAt"
        FROM projection_state
        WHERE projector = ${projector}
      `,
  });

  const listProjectionStateRows = SqlSchema.findAll({
    Request: Schema.Void,
    Result: ProjectionState,
    execute: () =>
      sql`
        SELECT
          projector,
          last_applied_sequence AS "lastAppliedSequence",
          updated_at AS "updatedAt"
        FROM projection_state
        ORDER BY projector ASC
      `,
  });

  const readMinLastAppliedSequence = SqlSchema.findOne({
    Request: Schema.Void,
    Result: MinLastAppliedSequenceRowSchema,
    execute: () =>
      sql`
        SELECT
          MIN(last_applied_sequence) AS "minLastAppliedSequence"
        FROM projection_state
      `,
  });

  const upsert: ProjectionStateRepositoryShape["upsert"] = (row) =>
    upsertProjectionStateRow(row).pipe(
      Effect.mapError(toPersistenceSqlError("ProjectionStateRepository.upsert:query")),
    );

  const upsertMany: ProjectionStateRepositoryShape["upsertMany"] = (rows) =>
    upsertProjectionStateRows(rows).pipe(
      Effect.mapError(toPersistenceSqlError("ProjectionStateRepository.upsertMany:query")),
    );

  const getByProjector: ProjectionStateRepositoryShape["getByProjector"] = (input) =>
    getProjectionStateRow(input).pipe(
      Effect.mapError(toPersistenceSqlError("ProjectionStateRepository.getByProjector:query")),
    );

  const listAll: ProjectionStateRepositoryShape["listAll"] = () =>
    listProjectionStateRows(undefined).pipe(
      Effect.mapError(toPersistenceSqlError("ProjectionStateRepository.listAll:query")),
    );

  const minLastAppliedSequence: ProjectionStateRepositoryShape["minLastAppliedSequence"] = () =>
    readMinLastAppliedSequence(undefined).pipe(
      Effect.mapError(
        toPersistenceSqlError("ProjectionStateRepository.minLastAppliedSequence:query"),
      ),
      Effect.map((row) => row.minLastAppliedSequence),
    );

  return {
    upsert,
    upsertMany,
    getByProjector,
    listAll,
    minLastAppliedSequence,
  } satisfies ProjectionStateRepositoryShape;
});

export const ProjectionStateRepositoryLive = Layer.effect(
  ProjectionStateRepository,
  makeProjectionStateRepository,
);

import { ApprovalRequestId, EventId, ThreadId, TurnId } from "@t3tools/contracts";
import { assert, it } from "@effect/vitest";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";

import { ProjectionThreadAttentionAuditRepository } from "../Services/ProjectionThreadAttentionAudit.ts";
import { SqlitePersistenceMemory } from "./Sqlite.ts";
import { ProjectionThreadAttentionAuditRepositoryLive } from "./ProjectionThreadAttentionAudit.ts";

const layer = it.layer(
  ProjectionThreadAttentionAuditRepositoryLive.pipe(Layer.provideMerge(SqlitePersistenceMemory)),
);

layer("ProjectionThreadAttentionAuditRepository", (it) => {
  it.effect("upserts idempotently and bounds newest-first reads", () =>
    Effect.gen(function* () {
      const repository = yield* ProjectionThreadAttentionAuditRepository;
      const threadId = ThreadId.make("thread-attention-audit");

      yield* Effect.forEach(
        Array.from({ length: 105 }, (_, index) => index + 1),
        (sequence) =>
          repository.upsert({
            eventId: EventId.make(`event-${String(sequence).padStart(3, "0")}`),
            threadId,
            turnId: sequence === 105 ? TurnId.make("turn-latest") : null,
            requestId: null,
            kind: sequence % 2 === 0 ? "thread.settled" : "thread.unsettled",
            sequence,
            occurredAt: "2026-01-01T00:00:00.000Z",
          }),
        { concurrency: 1 },
      );

      const bounded = yield* repository.listByThreadId({ threadId, limit: 1_000 });
      assert.strictEqual(bounded.length, 100);
      assert.strictEqual(bounded[0]?.sequence, 105);
      assert.strictEqual(bounded.at(-1)?.sequence, 6);

      yield* repository.upsert({
        eventId: EventId.make("event-105"),
        threadId,
        turnId: TurnId.make("turn-latest"),
        requestId: ApprovalRequestId.make("request-latest"),
        kind: "approval.resolved",
        sequence: 105,
        occurredAt: "2026-01-02T00:00:00.000Z",
      });

      const latest = yield* repository.listByThreadId({ threadId, limit: 1 });
      assert.deepEqual(latest, [
        {
          eventId: EventId.make("event-105"),
          threadId,
          turnId: TurnId.make("turn-latest"),
          requestId: ApprovalRequestId.make("request-latest"),
          kind: "approval.resolved",
          sequence: 105,
          occurredAt: "2026-01-02T00:00:00.000Z",
        },
      ]);
    }),
  );

  it.effect("deletes only the selected thread ledger", () =>
    Effect.gen(function* () {
      const repository = yield* ProjectionThreadAttentionAuditRepository;
      const firstThreadId = ThreadId.make("thread-attention-delete-1");
      const secondThreadId = ThreadId.make("thread-attention-delete-2");

      for (const [eventId, threadId] of [
        [EventId.make("event-delete-1"), firstThreadId],
        [EventId.make("event-delete-2"), secondThreadId],
      ] as const) {
        yield* repository.upsert({
          eventId,
          threadId,
          turnId: null,
          requestId: null,
          kind: "thread.settled",
          sequence: 1,
          occurredAt: "2026-01-01T00:00:00.000Z",
        });
      }

      yield* repository.deleteByThreadId({ threadId: firstThreadId });

      assert.deepEqual(
        yield* repository.listByThreadId({ threadId: firstThreadId, limit: 10 }),
        [],
      );
      assert.strictEqual(
        (yield* repository.listByThreadId({ threadId: secondThreadId, limit: 10 })).length,
        1,
      );
    }),
  );
});

import { OrchestrationThreadAttentionAuditEntry } from "@t3tools/contracts";
import * as Effect from "effect/Effect";
